-- 0037_seed_exercises_core_grip.sql
-- Semilla: core, colgados y agarre (plancha lateral, dead bug, hollow hold, dead hang…) con su técnica. Requiere 0026.
-- GENERADO por scripts/seed-sql.ts a partir de supabase/seed/*.json. No editar a mano.
-- Idempotente: se puede ejecutar varias veces.

insert into public.exercises (
  id, name, aliases, category, tracking_type, equipment, is_unilateral, is_compound,
  default_rest_s, technique_notes
) values
  ('side_plank', 'Plancha lateral', array['side plank', 'side bridge', 'plancha de lado', 'puente lateral']::text[], 'strength', 'time', array['bodyweight', 'mat']::text[], true, false, 45, 'Codo bajo el hombro, cuerpo en línea recta y cadera arriba.'),
  ('dead_bug', 'Dead bug', array['dead bugs', 'bicho muerto', 'insecto muerto', 'deadbug']::text[], 'strength', 'reps', array['mat']::text[], false, false, 45, 'Lumbar pegada al suelo mientras bajan brazo y pierna contrarios.'),
  ('hollow_hold', 'Hollow hold', array['hollow body hold', 'hollow body', 'posición hueca', 'banana', 'hollow']::text[], 'strength', 'time', array['mat']::text[], false, false, 60, 'Lumbar pegada al suelo, hombros y piernas despegados: forma de plátano.'),
  ('hollow_rock', 'Hollow rock', array['hollow rocks', 'balanceo hueco', 'mecedora hollow']::text[], 'strength', 'reps', array['mat']::text[], false, false, 60, 'Desde el hollow hold, balancéate adelante y atrás sin perder la forma.'),
  ('bird_dog', 'Bird dog', array['bird dogs', 'perro de caza', 'perro pájaro', 'cuadrupedia contralateral', 'superman en cuadrupedia']::text[], 'strength', 'reps', array['mat']::text[], false, false, 45, 'A cuatro patas, estira brazo y pierna contrarios sin mover la cadera.'),
  ('crunch', 'Crunch abdominal', array['crunch', 'crunches', 'abdominales', 'encogimientos', 'encogimiento abdominal']::text[], 'strength', 'reps', array['mat']::text[], false, false, 45, 'Despega solo los hombros enrollando la columna; la lumbar no se mueve del suelo.'),
  ('reverse_crunch', 'Crunch inverso', array['reverse crunch', 'encogimiento inverso', 'elevación de cadera tumbado']::text[], 'strength', 'reps', array['mat', 'bench']::text[], false, false, 45, 'Las rodillas van hacia el pecho y la cadera se despega un poco del suelo.'),
  ('bicycle_crunch', 'Crunch bicicleta', array['bicycle crunch', 'bicicleta abdominal', 'abdominales bicicleta', 'bicycle crunches']::text[], 'strength', 'reps', array['mat']::text[], false, false, 45, 'Codo hacia la rodilla contraria girando el tronco, no solo el codo.'),
  ('sit_up', 'Sit-up', array['sit up', 'situps', 'abdominal completo', 'abdominales completos', 'encogimiento completo']::text[], 'strength', 'reps', array['mat']::text[], false, false, 60, 'Abdominal completo hasta sentarse, enrollando la columna al subir y al bajar.'),
  ('v_up', 'V-up', array['v up', 'v-ups', 'navaja', 'jackknife', 'abdominal en v']::text[], 'strength', 'reps', array['mat']::text[], false, false, 60, 'Manos y pies se encuentran arriba formando una V; baja controlando.'),
  ('hanging_knee_raise', 'Elevación de rodillas colgado', array['hanging knee raise', 'knee raises', 'rodillas al pecho colgado', 'encogimientos colgado']::text[], 'strength', 'reps', array['pullup_bar']::text[], false, false, 60, 'Colgado sin balanceo, sube las rodillas al pecho enrollando la pelvis.'),
  ('hanging_leg_raise', 'Elevación de piernas colgado', array['hanging leg raise', 'leg raises', 'elevaciones de piernas en barra', 'piernas rectas colgado']::text[], 'strength', 'reps', array['pullup_bar']::text[], false, false, 75, 'Piernas estiradas hasta la horizontal o más, sin balanceo.'),
  ('toes_to_bar', 'Toes to bar', array['toes-to-bar', 't2b', 'pies a la barra', 'puntas a la barra']::text[], 'strength', 'reps', array['pullup_bar']::text[], false, true, 90, 'Desde colgado, los pies tocan la barra; en CrossFit se encadena con kipping.'),
  ('russian_twist', 'Russian twist', array['russian twists', 'giro ruso', 'giros rusos', 'rotaciones sentado']::text[], 'strength', 'weight_reps', array['medball', 'plate', 'bodyweight']::text[], false, false, 60, 'Sentado con el tronco inclinado, gira desde el tronco llevando el peso de lado a lado.'),
  ('cable_crunch', 'Crunch en polea', array['cable crunch', 'crunch de rodillas en polea', 'encogimiento en polea', 'rope crunch']::text[], 'strength', 'weight_reps', array['cable']::text[], false, false, 60, 'De rodillas, enrolla la columna llevando los codos a los muslos; la cadera no se mueve.'),
  ('cable_woodchop', 'Leñador en polea', array['woodchop', 'wood chop', 'woodchopper', 'leñador', 'cable woodchop']::text[], 'strength', 'weight_reps', array['cable', 'band']::text[], true, true, 60, 'Rotación diagonal del tronco con brazos casi estirados; giran cadera y pies.'),
  ('mountain_climber', 'Mountain climbers', array['mountain climber', 'escaladores', 'escalador', 'rodillas al pecho en plancha']::text[], 'functional', 'reps', array['bodyweight']::text[], false, true, 60, 'En plancha alta, lleva las rodillas al pecho alternando sin subir la cadera.'),
  ('plank_shoulder_tap', 'Plancha con toques de hombro', array['shoulder taps', 'plank shoulder tap', 'toques de hombro', 'plancha toque hombro']::text[], 'strength', 'reps', array['bodyweight']::text[], false, true, 45, 'En plancha alta, toca el hombro contrario sin que la cadera se balancee.'),
  ('copenhagen_plank', 'Plancha Copenhague', array['copenhagen plank', 'copenhagen', 'plancha de aductores', 'copenhague']::text[], 'strength', 'time', array['bench']::text[], true, false, 60, 'Plancha lateral con la pierna de arriba sobre un banco: trabajan los aductores.'),
  ('flutter_kicks', 'Flutter kicks', array['flutter', 'patadas de tijera', 'tijeras', 'patadas alternas']::text[], 'strength', 'time', array['mat']::text[], false, false, 45, 'Piernas estiradas cerca del suelo con pequeñas patadas alternas; lumbar abajo.'),
  ('superman', 'Superman', array['supermans', 'superman hold', 'extensión lumbar en el suelo', 'superman tumbado']::text[], 'strength', 'reps', array['mat']::text[], false, false, 45, 'Boca abajo, levanta brazos y piernas a la vez unos centímetros y aguanta.'),
  ('suitcase_carry', 'Suitcase carry', array['suitcase walk', 'paseo de maleta', 'transporte a una mano', 'farmer a una mano']::text[], 'functional', 'distance_time', array['kettlebell', 'dumbbell']::text[], true, true, 90, 'Peso en una sola mano y el tronco recto: el core evita que te inclines.'),
  ('farmer_hold', 'Farmer hold', array['farmers hold', 'farmer''s hold', 'agarre estático', 'sostener pesos', 'aguantar mancuernas']::text[], 'strength', 'time', array['kettlebell', 'dumbbell']::text[], false, true, 90, 'De pie, sostén dos pesos el máximo tiempo con hombros abajo y core firme.'),
  ('dead_hang', 'Dead hang (colgado pasivo)', array['dead hang', 'colgado', 'colgarse de la barra', 'colgado pasivo', 'hang']::text[], 'strength', 'time', array['pullup_bar']::text[], false, false, 60, 'Colgado con los brazos estirados y los hombros relajados: agarre y descompresión.'),
  ('active_hang', 'Colgado activo', array['active hang', 'colgado escapular', 'hang activo', 'colgado con escápulas activas']::text[], 'strength', 'time', array['pullup_bar']::text[], false, false, 60, 'Colgado con los brazos estirados pero los hombros tirando hacia abajo.'),
  ('scapular_pull_up', 'Dominada escapular', array['scapular pull-up', 'scap pull up', 'scap pulls', 'retracción escapular en barra']::text[], 'strength', 'reps', array['pullup_bar']::text[], false, false, 60, 'Sin doblar los codos, sube unos centímetros llevando los hombros abajo.'),
  ('towel_hang', 'Colgado con toalla', array['towel hang', 'colgado de toallas', 'agarre con toalla', 'towel grip hang']::text[], 'strength', 'time', array['pullup_bar', 'towel']::text[], false, false, 90, 'Colgado agarrando dos toallas pasadas por la barra: agarre muy exigente.'),
  ('plate_pinch', 'Pinza con discos', array['plate pinch', 'pinch grip', 'agarre de pinza', 'pellizco de discos']::text[], 'strength', 'time', array['plate']::text[], false, false, 60, 'Sujeta dos discos lisos juntos con la punta de los dedos y el pulgar.'),
  ('wrist_curl', 'Curl de muñeca', array['wrist curl', 'flexión de muñeca', 'curl de antebrazo', 'wrist curls']::text[], 'strength', 'weight_reps', array['dumbbell', 'barbell']::text[], false, false, 60, 'Antebrazos apoyados y palmas arriba: solo se mueve la muñeca.'),
  ('reverse_wrist_curl', 'Curl de muñeca inverso', array['reverse wrist curl', 'extensión de muñeca', 'curl de antebrazo inverso']::text[], 'strength', 'weight_reps', array['dumbbell', 'barbell']::text[], false, false, 60, 'Como el curl de muñeca pero con las palmas hacia abajo; peso ligero.')
on conflict (id) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  category = excluded.category,
  tracking_type = excluded.tracking_type,
  equipment = excluded.equipment,
  is_unilateral = excluded.is_unilateral,
  is_compound = excluded.is_compound,
  default_rest_s = excluded.default_rest_s,
  technique_notes = excluded.technique_notes
where public.exercises.owner_id is null;

-- Músculos: se reescriben para que la semilla sea la fuente de verdad.
delete from public.exercise_muscles where exercise_id in ('side_plank', 'dead_bug', 'hollow_hold', 'hollow_rock', 'bird_dog', 'crunch', 'reverse_crunch', 'bicycle_crunch', 'sit_up', 'v_up', 'hanging_knee_raise', 'hanging_leg_raise', 'toes_to_bar', 'russian_twist', 'cable_crunch', 'cable_woodchop', 'mountain_climber', 'plank_shoulder_tap', 'copenhagen_plank', 'flutter_kicks', 'superman', 'suitcase_carry', 'farmer_hold', 'dead_hang', 'active_hang', 'scapular_pull_up', 'towel_hang', 'plate_pinch', 'wrist_curl', 'reverse_wrist_curl');

