-- Técnica (pasos clave y errores típicos).
update public.exercises e set
  technique_steps = v.steps,
  technique_mistakes = v.mistakes
from (values
  ('side_plank', array['Túmbate de lado con el codo justo debajo del hombro y las piernas estiradas.', 'Levanta la cadera hasta que cabeza, cadera y tobillos queden en línea.', 'Aprieta glúteos y abdomen y respira sin soltar la posición.', 'Repite por el otro lado con el mismo tiempo.']::text[], array['Dejar caer la cadera hacia el suelo.', 'Apoyar el codo por delante o por detrás del hombro.', 'Girar el pecho hacia el suelo.']::text[]),
  ('dead_bug', array['Túmbate boca arriba con brazos al techo y rodillas a 90° sobre la cadera.', 'Pega la zona lumbar al suelo apretando el abdomen.', 'Baja a la vez un brazo y la pierna contraria sin que la lumbar se despegue.', 'Vuelve al centro y alterna lados; cuenta una repetición por lado.']::text[], array['Arquear la espalda al estirar la pierna.', 'Ir deprisa y sin control.', 'Contener la respiración.']::text[]),
  ('hollow_hold', array['Túmbate boca arriba y pega la zona lumbar al suelo.', 'Levanta hombros y piernas estiradas unos centímetros, brazos junto a las orejas.', 'Aguanta respirando corto sin que la lumbar se despegue.', 'Si cuesta, flexiona las rodillas o lleva los brazos junto al cuerpo.']::text[], array['Despegar la lumbar del suelo (la espalda se arquea).', 'Subir mucho las piernas para que sea más fácil.', 'Tensar el cuello en vez del abdomen.']::text[]),
  ('hollow_rock', array['Colócate en hollow hold: lumbar pegada, hombros y piernas despegados.', 'Balancéate hacia delante y hacia atrás como una mecedora.', 'El movimiento sale del abdomen firme, no de doblar cadera o rodillas.']::text[], array['Doblarse por la cadera y perder la forma de plátano.', 'Impulsarse con los brazos.', 'Seguir cuando ya no se mantiene la lumbar abajo.']::text[]),
  ('bird_dog', array['Ponte a cuatro patas con manos bajo los hombros y rodillas bajo la cadera.', 'Estira a la vez un brazo y la pierna contraria hasta que queden en línea con la espalda.', 'Aguanta un segundo sin que la cadera gire y vuelve despacio.', 'Alterna lados; cuenta una repetición por lado.']::text[], array['Levantar la pierna por encima de la cadera y arquear la lumbar.', 'Girar la cadera hacia el lado de la pierna que sube.', 'Hacerlo rápido, sin pausa.']::text[]),
  ('crunch', array['Túmbate boca arriba con las rodillas dobladas y los pies apoyados.', 'Manos en el pecho o junto a las sienes, sin tirar de la cabeza.', 'Sube enrollando la columna hasta despegar los omóplatos y suelta el aire.', 'Baja despacio sin dejar caer la cabeza.']::text[], array['Tirar del cuello con las manos.', 'Subir con impulso hasta sentarse del todo.', 'Bajar de golpe.']::text[]),
  ('reverse_crunch', array['Túmbate boca arriba con las rodillas dobladas a 90° y los brazos junto al cuerpo.', 'Lleva las rodillas hacia el pecho despegando la cadera del suelo con el abdomen.', 'Baja despacio hasta que los pies casi toquen el suelo.']::text[], array['Balancear las piernas para coger impulso.', 'Empujar el suelo con las manos.', 'Dejar que la lumbar se arquee al bajar.']::text[]),
  ('bicycle_crunch', array['Túmbate boca arriba con las manos junto a las sienes y los hombros despegados.', 'Lleva una rodilla al pecho mientras estiras la otra pierna.', 'Gira el tronco para acercar el hombro contrario a la rodilla que sube.', 'Alterna lados de forma controlada; cuenta una repetición por lado.']::text[], array['Mover solo los codos sin girar el tronco.', 'Tirar de la cabeza con las manos.', 'Ir tan rápido que se pierde el control.']::text[]),
  ('sit_up', array['Túmbate con las rodillas dobladas y los pies apoyados (o sujetos).', 'Sube enrollando la columna hasta quedar sentado, con los brazos al frente.', 'Baja vértebra a vértebra hasta apoyar los hombros.']::text[], array['Lanzar los brazos para subir con impulso.', 'Bajar de golpe golpeando la espalda.', 'Tirar del cuello.']::text[]),
  ('v_up', array['Túmbate estirado con los brazos por encima de la cabeza.', 'Sube a la vez piernas estiradas y tronco hasta que las manos busquen los pies.', 'Baja despacio a la posición estirada sin apoyar del todo.']::text[], array['Doblar mucho las rodillas para llegar.', 'Caer de golpe al bajar.', 'Arquear la lumbar en la posición estirada.']::text[]),
  ('hanging_knee_raise', array['Cuélgate de la barra con agarre firme y los hombros activos.', 'Sube las rodillas hacia el pecho enrollando la pelvis hacia arriba.', 'Baja despacio hasta estirar las piernas sin balancearte.']::text[], array['Balancearse para subir las piernas.', 'Subir solo hasta la cadera sin enrollar la pelvis.', 'Soltar los hombros y colgar pasivo.']::text[]),
  ('hanging_leg_raise', array['Cuélgate de la barra con los hombros activos y el cuerpo quieto.', 'Sube las piernas estiradas al menos hasta la horizontal enrollando la pelvis.', 'Baja controlando hasta la vertical sin balancearte.']::text[], array['Usar el balanceo del cuerpo para subir.', 'Doblar las rodillas cuando se quiere hacer con piernas rectas.', 'Arquear la espalda al bajar.']::text[]),
  ('toes_to_bar', array['Cuélgate con agarre de hombros y empuja la barra hacia abajo con los brazos estirados.', 'Sube las piernas enrollando la pelvis hasta tocar la barra con los pies.', 'Baja controlando y vuelve a la posición colgada antes de la siguiente.']::text[], array['Balanceo descontrolado que no se puede encadenar.', 'No tocar la barra con los dos pies a la vez.', 'Soltar los hombros abajo.']::text[]),
  ('russian_twist', array['Siéntate con las rodillas dobladas y el tronco inclinado unos 45° hacia atrás.', 'Sujeta el peso (o junta las manos) delante del pecho, con la espalda recta.', 'Gira el tronco a un lado y al otro llevando el peso junto a la cadera.', 'Para más dificultad, despega los pies del suelo.']::text[], array['Mover solo los brazos sin girar el tronco.', 'Redondear la espalda.', 'Ir tan rápido que el peso arrastra al cuerpo.']::text[]),
  ('cable_crunch', array['Arrodíllate frente a la polea alta con la cuerda junto a la cabeza.', 'Mantén la cadera quieta y enrolla la columna llevando los codos hacia los muslos.', 'Aprieta el abdomen abajo y vuelve despacio estirando la espalda.']::text[], array['Sentarse sobre los talones y tirar con la cadera.', 'Tirar con los brazos en vez de con el abdomen.', 'Demasiado peso y recorrido corto.']::text[]),
  ('cable_woodchop', array['Colócate de lado a la polea, alta o baja, con los pies a la anchura de los hombros.', 'Coge el agarre con las dos manos y los brazos casi estirados.', 'Lleva el agarre en diagonal hasta el lado contrario girando tronco y cadera.', 'Vuelve despacio resistiendo el tirón y repite; luego cambia de lado.']::text[], array['Tirar con los brazos doblados en vez de girar.', 'Bloquear los pies y retorcer la zona lumbar.', 'Volver de golpe dejando que la polea tire.']::text[]),
  ('mountain_climber', array['Ponte en plancha alta con las manos bajo los hombros.', 'Lleva una rodilla hacia el pecho y vuelve mientras sube la otra.', 'Mantén la cadera a la altura de los hombros y el ritmo constante.', 'Cuenta una repetición por pierna.']::text[], array['Subir la cadera muy por encima de los hombros.', 'Tener las manos por delante de los hombros.', 'Tocar el suelo solo con la punta sin llevar la rodilla al pecho.']::text[]),
  ('plank_shoulder_tap', array['Ponte en plancha alta con los pies algo separados.', 'Levanta una mano y toca el hombro contrario.', 'Vuelve a apoyar y cambia de mano sin que la cadera se mueva.']::text[], array['Balancear la cadera de lado a lado.', 'Juntar demasiado los pies (pierde estabilidad).', 'Ir deprisa en vez de controlar.']::text[]),
  ('copenhagen_plank', array['Túmbate de lado junto a un banco y apoya sobre él la parte interna de la rodilla o del pie de arriba.', 'Apoya el codo bajo el hombro y levanta la cadera hasta alinear el cuerpo.', 'Aguanta apretando la pierna de arriba contra el banco.', 'Versión fácil: con la rodilla en el banco; difícil: con el pie.']::text[], array['Dejar caer la cadera.', 'Empezar con el pie en el banco sin haber dominado la rodilla.', 'Girar el tronco hacia el suelo.']::text[]),
  ('flutter_kicks', array['Túmbate boca arriba con las manos bajo los glúteos o junto al cuerpo.', 'Pega la lumbar al suelo y levanta las piernas estiradas unos centímetros.', 'Sube y baja las piernas alternas con recorridos cortos y rápidos.']::text[], array['Despegar la lumbar del suelo.', 'Doblar mucho las rodillas.', 'Contener la respiración.']::text[]),
  ('superman', array['Túmbate boca abajo con los brazos estirados por delante.', 'Aprieta glúteos y levanta brazos, pecho y piernas unos centímetros.', 'Aguanta un par de segundos mirando al suelo y baja despacio.']::text[], array['Levantar la cabeza y forzar el cuello.', 'Subir con impulso y demasiado alto.', 'Doblar las rodillas.']::text[]),
  ('suitcase_carry', array['Coge una kettlebell o mancuerna con una mano, como una maleta.', 'Ponte erguido con los hombros nivelados y el abdomen firme.', 'Camina con pasos normales sin inclinarte hacia el peso.', 'Haz la misma distancia con la otra mano.']::text[], array['Inclinarse hacia el lado del peso (o compensar al contrario).', 'Encoger el hombro que lleva el peso.', 'Pasos largos y rápidos que hacen balancear la carga.']::text[]),
  ('farmer_hold', array['Coge dos pesos iguales del suelo con la espalda neutra, como en un peso muerto.', 'Quédate erguido con los brazos estirados y los hombros abajo y atrás.', 'Aprieta los agarres y el abdomen y aguanta respirando con normalidad.']::text[], array['Encoger los hombros hacia las orejas.', 'Dejar que los pesos se abran las muñecas.', 'Soltar los pesos de golpe al terminar.']::text[]),
  ('dead_hang', array['Coge la barra con las manos a la anchura de los hombros.', 'Levanta los pies y cuélgate con los brazos estirados.', 'Relaja los hombros (suben hacia las orejas) y respira tranquilo.', 'Baja con los pies en un cajón o al suelo, sin soltarte de golpe.']::text[], array['Saltar a la barra y soltarse desde arriba.', 'Balancearse.', 'Seguir con dolor en el hombro: en ese caso, para.']::text[]),
  ('active_hang', array['Cuélgate de la barra con los brazos estirados.', 'Lleva los hombros hacia abajo y atrás, alejándolos de las orejas, sin doblar los codos.', 'Aguanta esa posición con el pecho algo abierto y el abdomen firme.']::text[], array['Doblar los codos (se convierte en una dominada).', 'Dejar que los hombros vuelvan a subir.', 'Arquear mucho la espalda.']::text[]),
  ('scapular_pull_up', array['Cuélgate con los brazos estirados y los hombros relajados.', 'Tira de los hombros hacia abajo y atrás: el cuerpo sube unos centímetros.', 'Aguanta un segundo y vuelve a soltar despacio.']::text[], array['Doblar los codos para subir más.', 'Hacerlo con balanceo.', 'Soltar de golpe abajo.']::text[]),
  ('towel_hang', array['Pasa dos toallas por la barra a la anchura de los hombros.', 'Agarra cada toalla con toda la mano y cuélgate despacio.', 'Aguanta con los hombros activos y baja antes de que se escurra el agarre.']::text[], array['Usar toallas finas o mojadas que resbalan.', 'Soltarse de golpe.', 'Empezar sin dominar el colgado normal.']::text[]),
  ('plate_pinch', array['Junta dos discos con la cara lisa hacia fuera.', 'Cógelos en pinza: dedos por un lado y pulgar por el otro.', 'Levántalos junto al costado con el brazo estirado y aguanta.']::text[], array['Ayudarse apoyando los discos en la pierna.', 'Demasiado peso: se caen sobre los pies.', 'Doblar la muñeca.']::text[]),
  ('wrist_curl', array['Siéntate y apoya los antebrazos en los muslos o en un banco, con las palmas hacia arriba.', 'Deja que la barra o las mancuernas bajen rodando hasta los dedos.', 'Sube cerrando la mano y flexionando la muñeca, sin mover el antebrazo.']::text[], array['Levantar los antebrazos del apoyo.', 'Recorrido corto.', 'Usar tanto peso que hay que dar tirones.']::text[]),
  ('reverse_wrist_curl', array['Apoya los antebrazos con las palmas hacia abajo y las muñecas fuera del apoyo.', 'Baja el peso doblando la muñeca y súbelo extendiéndola.', 'Haz el movimiento lento en los dos sentidos.']::text[], array['Peso demasiado alto: es un músculo pequeño.', 'Ayudarse con el codo.', 'Ir con rebote.']::text[])
) as v (id, steps, mistakes)
where e.id = v.id and e.owner_id is null;
